    /// The outlines, scaled to fit `rect` and centred in it. Filled with
    /// the even-odd rule, as Boundless's file fills its own.
    func path(in rect: CGRect) -> Path {
        var path = Path()
        for outline in outlines {
            let scanner = Scanner(string: outline)
            var command: Character = "M"
            func point() -> CGPoint {
                CGPoint(x: scanner.scanDouble() ?? 0, y: scanner.scanDouble() ?? 0)
            }
            while !scanner.isAtEnd {
                if let letters = scanner.scanCharacters(from: .letters) {
                    for letter in letters {
                        command = letter
                        if letter == "Z" { path.closeSubpath() }
                    }
                    continue
                }
                switch command {
                case "M":
                    path.move(to: point())
                    command = "L"
                case "H":
                    let x = scanner.scanDouble() ?? 0
                    path.addLine(to: CGPoint(x: x, y: path.currentPoint?.y ?? 0))
                case "V":
                    let y = scanner.scanDouble() ?? 0
                    path.addLine(to: CGPoint(x: path.currentPoint?.x ?? 0, y: y))
                case "C":
                    let first = point(), second = point()
                    path.addCurve(to: point(), control1: first, control2: second)
                default: path.addLine(to: point())
                }
            }
        }
        let scale = min(rect.width / box.width, rect.height / box.height)
        return path.applying(
            CGAffineTransform(
                translationX: rect.midX - box.width * scale / 2, y: rect.midY - box.height * scale / 2
            )
            .scaledBy(x: scale, y: scale)
            .translatedBy(x: -origin.x, y: -origin.y))
    }
}

/// Boundless's mark, then Tempo's: who answers a Token Inference chat and
/// where it is paid. Read by VoiceOver through whatever holds them.
struct BoundlessTempoMarks: View {
    var body: some View {
        HStack(spacing: 6) {
            BrandMark.boundless
                .fill(style: FillStyle(eoFill: true))
                .frame(width: 16, height: 16)
            BrandMark.tempo
                .fill()
                .frame(width: 13, height: 13)
        }
        .accessibilityHidden(true)
    }
}

/// The two marks as a button, with the note behind them: where Token
/// Inference shows who answers and where it is paid.
struct BoundlessTempoButton: View {
    var arrowEdge: Edge = .bottom

    var body: some View {
        InfoButton("Boundless and Tempo", hint: BoundlessTempoNote.words, arrowEdge: arrowEdge) {
            BoundlessTempoMarks()
        } note: {
            BoundlessTempoNote()
        }
    }
}

/// How Token Inference uses the two, with Boundless's own post about it.
struct BoundlessTempoNote: View {
    static let words =
        "Boundless runs the model. Cloak pays it for each request in USDC.e on Tempo, from the wallet on this Mac. There's no account at Boundless and no key to keep."
    static let post = URL(string: "https://boundless.network/news/mpp-payments")!

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(Self.words)
                .textSelection(.enabled)
                .fixedSize(horizontal: false, vertical: true)
            HStack(spacing: 12) {
                Link("Boundless post", destination: Self.post)
                Link("Tempo", destination: URL(string: "https://tempo.xyz")!)
                Link("MPP", destination: URL(string: "https://mpp.dev")!)
                Link("GitHub", destination: URL(string: "https://github.com/tempoxyz/mpp-rs")!)
            }
        }
        .font(.callout)
        .padding(14)
        .frame(width: 310, alignment: .leading)
    }
}

